---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Line chart: Today so far and projected, against yesterday, with a range switch, a project picker, toggles and a readout.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change line-chart.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './line-chart.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="line-chart" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="lnx panel">
  <div class="lnx-h">
    <div class="lnx-tl"><span class="lnx-t">Active editors</span><button class="lnx-pk" data-pop="#lnx-pp" aria-haspopup="menu" aria-expanded="false"><span class="lnx-mk" aria-hidden="true"></span><span class="lnx-pn"></span><svg class="i xs"><use href="#i-chev-d"/></svg></button></div>
    <div class="seg2 lnx-rg" role="group" aria-label="Range"><button aria-pressed="true" data-v="d">Day</button><button aria-pressed="false" data-v="w">Week</button><button aria-pressed="false" data-v="m">Month</button></div>
  </div>
  <div class="pop lnx-pp" id="lnx-pp" role="menu" aria-label="Project"></div>
  <div class="lnx-pl">
    <div class="lnx-y num" aria-hidden="true"></div>
    <div class="lnx-ch" tabindex="0" role="group" aria-roledescription="line chart"><svg class="lnx-svg" aria-hidden="true"></svg><span class="lnx-x"></span><span class="lnx-pt" style="color:var(--dm-lnx-cmp)"></span><span class="lnx-pt" style="color:var(--dm-lnx-line)"></span><span class="lnx-now"></span><span class="lnx-aim" aria-hidden="true"></span><div class="lnx-tt" aria-hidden="true"><div class="lnx-tt-h"></div><div class="lnx-tt-r"><i></i><span></span><b class="num"></b></div><div class="lnx-tt-r c"><i></i><span></span><b class="num"></b></div></div></div>
    <div class="lnx-ax num" aria-hidden="true"></div>
  </div>
  <div class="lnx-lg"><button class="lnx-k" aria-pressed="true" data-s="a"><i></i><span></span></button><button class="lnx-k p" aria-pressed="true" data-s="p"><i></i><span>Projected</span></button><button class="lnx-k c" aria-pressed="true" data-s="b"><i></i><span></span></button></div>
  <p class="lnx-sr" aria-live="polite"></p>
  <div class="lnx-sr"><table></table></div>
</div>
  </Fragment></div>
</div>
<script>
  import './line-chart.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Line chart ---------- */
/* one metric over a period, against the period before (owner, 21 Nov): straight segments with sharp joins, a saturated line in the accent, and a fill that fades from the line's colour
   at the top to nothing at the bottom. A quiet head: the title, a picker for whose numbers they are, and the range switch, with
   a hairline under them. Under it the plot: the values on the left, dashed vertical gridlines and no horizontal ones, the period
   before as a dotted line in the chart palette's second colour across the whole period, and this period as a solid line up to
   now, with an open ring and "Now" under it, then projected to the period's end as a dotted line in its own colour over a
   fill at half strength, so the chart always runs full width (owner, 21 Nov: "I never seen charts that end mid way"). A legend under the plot names both lines and turns each on and off. Pointing at the plot, or the arrow keys on it, shows a dashed guide, a ring on each line and a readout card
   beside the guide on the side with room, and the point's name becomes a grey chip on the axis. The content sits 16px in from
   every edge; the picker's and the switch's hover boxes reach out round their words */
.lnx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-4);--dm-row:color-mix(in srgb,var(--dm-fg) 5%,transparent);
  --dm-lnx-line:var(--dm-accent-mark,var(--dm-accent));--dm-lnx-cmp:var(--dm-c2);--dm-lnx-fill:.2;--dm-lnx-pfill:.1;--dm-lnx-grid:var(--dm-line);--dm-lnx-guide:color-mix(in srgb,var(--dm-fg) 38%,transparent)}
:root[data-theme="dark"] .lnx{--dm-lnx-fill:.3;--dm-lnx-pfill:.15}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .lnx{--dm-lnx-fill:.3;--dm-lnx-pfill:.15}}
.lnx-h{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-2) var(--dm-s-3);flex-wrap:wrap;padding-bottom:var(--dm-s-4);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.lnx-tl{display:flex;align-items:center;gap:6px;min-width:0;font-size:13.5px;line-height:20px}
.lnx-t{color:var(--dm-muted);white-space:nowrap}
/* the picker: its mark and words in the text colour, no edge until hovered; its hover box reaches out round them */
.lnx-pk{display:inline-flex;align-items:center;gap:6px;height:28px;margin:-4px -5px -4px 0;padding:0 5px 0 8px;border-radius:var(--dm-r-sm);color:var(--dm-fg);font-weight:500;white-space:nowrap;transition:background-color var(--dm-t-fast) var(--dm-ease)}
.lnx-pk[aria-expanded="true"]{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.lnx-pk:hover{background:var(--dm-row)}}
.lnx-pk .i{color:var(--dm-muted);margin-left:-2px}
.lnx-mk{width:18px;height:18px;flex:none;display:grid;place-items:center;border-radius:calc(5px * var(--dm-rk-s,var(--dm-rk)));font-size:10.5px;font-weight:500;line-height:1;background:var(--dm-mk,var(--dm-av-b));color:var(--dm-mk-ink,var(--dm-av-b-ink))}
.pop.lnx-pp{min-width:188px}
.lnx-pp .mi{gap:var(--dm-s-2)}
.lnx-rg button{font-size:12px;height:26px;padding:0 9px}
/* on a narrow card the switch goes under the title, as wide as the content, its parts sharing the width */
.lnx{container:lnx/inline-size}
@container lnx (max-width:375px){.lnx-h{flex-direction:column;align-items:stretch}.lnx-rg{display:flex}.lnx-rg button{flex:1}.lnx-pk{margin-top:0;margin-bottom:0}}
/* and on a phone the legend's three lines take two columns, so it is two rows whatever the range calls them, and switching the
   range never changes the card's height */
@container lnx (max-width:300px){.lnx .lnx-lg{display:grid;grid-template-columns:max-content max-content;gap:2px var(--dm-s-1);justify-content:start}}
/* the plot: the values in a column on the left, each centred on its height; the axis under the drawing */
.lnx-pl{display:grid;grid-template-rows:auto auto;grid-template-columns:auto minmax(0,1fr);column-gap:var(--dm-s-3);row-gap:var(--dm-s-2)}
.lnx-y{display:flex;flex-direction:column;justify-content:space-between;margin:-8px 0;font-size:12px;line-height:16px;color:var(--dm-muted);text-align:right;white-space:nowrap}
.lnx-ch{position:relative;height:168px;touch-action:pan-y}
.lnx-ch:focus-visible{outline-offset:6px}
.lnx-svg{position:absolute;left:0;top:0;width:100%;height:100%;display:block;overflow:visible}
.lnx-svg .gl{stroke:var(--dm-lnx-grid);stroke-width:1;stroke-dasharray:3 4}
.lnx-svg .ln{fill:none;stroke:var(--dm-lnx-line);stroke-width:2;stroke-linejoin:miter;stroke-miterlimit:8;stroke-linecap:butt}
.lnx-svg :is(.cmp,.prj){fill:none;stroke:var(--dm-lnx-cmp);stroke-width:2;stroke-linecap:round;stroke-dasharray:0 5}
.lnx-svg .prj{stroke:var(--dm-lnx-line)}
/* now: an open ring on the line's end, with a dot of the line's colour inside */
.lnx-now{position:absolute;left:0;top:0;width:12px;height:12px;margin:-6px 0 0 -6px;border-radius:50%;background:radial-gradient(circle,var(--dm-lnx-line) 2px,var(--dm-surface) 2.6px);box-shadow:inset 0 0 0 2px var(--dm-lnx-line);pointer-events:none;transition:opacity var(--dm-t-fast) var(--dm-ease)}
/* the guide, the rings and the readout show while the plot is pointed at or has the keyboard's focus */
/* where the demo's pointer aims: an empty box centred on the point it reads */
.lnx-aim{position:absolute;left:0;top:0;width:16px;height:16px;margin:-8px 0 0 -8px;pointer-events:none}
.lnx-x{position:absolute;top:0;bottom:0;left:0;width:1px;margin-left:-.5px;background:repeating-linear-gradient(to bottom,var(--dm-lnx-guide) 0 3px,transparent 3px 7px);opacity:0;transition:opacity var(--dm-t-fast) var(--dm-ease);pointer-events:none}
.lnx-pt{position:absolute;left:0;top:0;width:10px;height:10px;margin:-5px 0 0 -5px;border-radius:50%;background:var(--dm-surface);box-shadow:inset 0 0 0 2px currentColor;opacity:0;transition:opacity var(--dm-t-fast) var(--dm-ease);pointer-events:none}
.lnx-tt{position:absolute;left:0;top:0;z-index:2;min-width:156px;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-raised);box-shadow:var(--dm-shadow-pop);font-size:12.5px;line-height:18px;white-space:nowrap;opacity:0;transform:translateY(4px);transition:opacity var(--dm-t-fast) var(--dm-ease),transform var(--dm-t) var(--dm-ease);pointer-events:none}
.lnx-tt-h{padding:6px 10px;font-size:12px;color:var(--dm-muted);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.lnx-tt-r{display:flex;align-items:center;gap:var(--dm-s-2);padding:6px 10px}
.lnx-tt-r+.lnx-tt-r{padding-top:0}
.lnx-tt-r i{width:12px;height:2px;flex:none;border-radius:1px;background:var(--dm-lnx-line)}
.lnx-tt-r.c i{height:2px;background:radial-gradient(circle,var(--dm-lnx-cmp) .9px,transparent 1.1px) 0 50%/4px 2px repeat-x}
.lnx-tt-r.p i{background:radial-gradient(circle,var(--dm-lnx-line) .9px,transparent 1.1px) 0 50%/4px 2px repeat-x}
.lnx-tt-r span{flex:1;color:var(--dm-fg2)}
.lnx-tt-r b{font-weight:500;color:var(--dm-fg)}
.lnx-tt-r[hidden]{display:none}
.lnx.on .lnx-x,.lnx.on .lnx-tt,.lnx.on .lnx-pt.on{opacity:1}
.lnx.on .lnx-tt{transform:none}
/* the axis: the period's first point on the left, Now under its point in the accent's text colour, the last on the right; the
   point pointed at is a grey chip, and any label it would touch steps aside */
.lnx-ax{grid-column:2;position:relative;height:20px;font-size:12px;line-height:20px;color:var(--dm-muted)}
.lnx-ax span{position:absolute;top:0;left:0;white-space:nowrap;transition:opacity var(--dm-t-fast) var(--dm-ease)}
/* the last label ends on the plot's right edge (6px in when it is Now's own, so it sits under the ring) */
.lnx-ax .lnx-z:not([style]){left:auto;right:0}
.lnx-ax .lnx-z.lnx-nw:not([style]){right:6px}
.lnx-ax .lnx-nw{color:var(--dm-accent-fg,var(--dm-accent))}
.lnx-ax .lnx-tk{padding:0 6px;border-radius:var(--dm-r-xs);background:var(--dm-chip);color:var(--dm-fg2);opacity:0}
.lnx.on .lnx-ax .lnx-tk{opacity:1}
.lnx-ax :is(.lnx-off,.lnx-hid){opacity:0}
/* the legend: each line's swatch and name, a toggle; its words start on the content's edge and its hover reaches out round them.
   On this card the toggles' boxes sit on the content's 16px column instead, so nothing reaches nearer the card's edge than the
   rest of its content (owner, 21 Nov: insets measured in every style); a page that reuses the legend under a plot of its own
   keeps the hover reaching out */
.lnx-lg{display:flex;flex-wrap:wrap;gap:var(--dm-s-1);margin:-8px -8px -5px}
.lnx:has(>.lnx-h>.lnx-tl)>.lnx-lg{margin:-8px 0 0}
.lnx-k{display:flex;align-items:center;gap:6px;height:26px;padding:0 8px;border-radius:var(--dm-r-pill);font-size:12px;color:var(--dm-muted);transition:color var(--dm-t-fast) var(--dm-ease),background-color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.lnx-k:hover{background:var(--dm-row)}}
.lnx-k[aria-pressed="true"]{color:var(--dm-fg)}
.lnx-k i{width:12px;height:2px;flex:none;border-radius:1px;background:var(--dm-lnx-line);transition:opacity var(--dm-t-fast) var(--dm-ease)}
.lnx-k.c i{background:radial-gradient(circle,var(--dm-lnx-cmp) .9px,transparent 1.1px) 0 50%/4px 2px repeat-x}
.lnx-k.p i{background:radial-gradient(circle,var(--dm-lnx-line) .9px,transparent 1.1px) 0 50%/4px 2px repeat-x}
.lnx-k[aria-pressed="false"] i{opacity:.3}
.lnx-svg :is(.ln,.ar,.cmp,.prj,.par){transition:opacity var(--dm-t) var(--dm-ease)}
.lnx.lnx-noa .lnx-svg :is(.ln,.ar),.lnx.lnx-nop .lnx-svg :is(.prj,.par),.lnx.lnx-nob .lnx-svg .cmp{opacity:0}
.lnx.lnx-noa .lnx-now{visibility:hidden}
.lnx-sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}
.lnx-sr th{font-weight:400}
@media (prefers-reduced-motion:reduce){.lnx :is(.lnx-x,.lnx-pt,.lnx-tt,.lnx-now,.lnx-ax span){transition:none}}
/* Blueprint: square marks (the ring, the hover marks, the swatches) and square dots on the line before */
/* Clean: the project marks are monochrome, a solid ink tile like a logo, its letter in the ink's own text colour */
:root[data-style="clean"] .lnx-mk,:root [data-style="clean"] .lnx-mk,:root [data-style="clean"].lnx-mk{background:var(--dm-ink);color:var(--dm-on-ink)}
/* Clean (owner, 21 Nov: Clean must read as Clean at a glance): the head and the legend sit on off-white strips that follow the
   card's corners, their controls on the content's 16px column and 8px from the strip's top and bottom (the title's words on
   the column, the switch ending on it). The picker's hover is a pill. The legend's toggles are flat pills: a line that is shown
   has the stronger neutral fill (Clean's selected state), one that is hidden none until pointed at, when it takes Clean's one
   hover fill. The readout is
   Clean's popover: its corners, its 6px inset and rows like a menu's, scaling and fading in over 220ms. The pointed-at tick is
   a pill. The strips belong to this card's own head (the title and the picker): a page that reuses the plot under a head of
   its own keeps its layout */
:root[data-style="clean"] .lnx>.lnx-h:has(>.lnx-tl),:root [data-style="clean"] .lnx>.lnx-h:has(>.lnx-tl),:root [data-style="clean"].lnx>.lnx-h:has(>.lnx-tl){margin:calc(-1 * var(--dm-s-4)) calc(-1 * var(--dm-s-4)) 0;padding:8px var(--dm-s-4);background:var(--dm-strip);border-bottom:1px solid var(--dm-line);border-radius:var(--dm-r-card) var(--dm-r-card) 0 0}
:root[data-style="clean"] .lnx-pk,:root [data-style="clean"] .lnx-pk,:root [data-style="clean"].lnx-pk{border-radius:var(--dm-r-pill)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] :is(.lnx-pk:hover,.lnx-pk[aria-expanded="true"]),:root [data-style="clean"] :is(.lnx-pk:hover,.lnx-pk[aria-expanded="true"]),:root [data-style="clean"]:is(.lnx-pk:hover,.lnx-pk[aria-expanded="true"]){background:var(--dm-hover)}}
:root[data-style="clean"] .lnx:has(>.lnx-h>.lnx-tl)>.lnx-lg,:root [data-style="clean"] .lnx:has(>.lnx-h>.lnx-tl)>.lnx-lg,:root [data-style="clean"].lnx:has(>.lnx-h>.lnx-tl)>.lnx-lg{margin:0 calc(-1 * var(--dm-s-4)) calc(-1 * var(--dm-s-4));padding:8px var(--dm-s-4);gap:6px;background:var(--dm-strip);border-top:1px solid var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .lnx:has(>.lnx-h>.lnx-tl)>.lnx-lg .lnx-k,:root [data-style="clean"] .lnx:has(>.lnx-h>.lnx-tl)>.lnx-lg .lnx-k,:root [data-style="clean"].lnx:has(>.lnx-h>.lnx-tl)>.lnx-lg .lnx-k{height:28px;padding:0 10px}
/* (on a phone its two columns share the width, the second ending on the content's right edge like the switch above) */
@container lnx (max-width:300px){:root[data-style="clean"] .lnx:has(>.lnx-h>.lnx-tl)>.lnx-lg,:root [data-style="clean"] .lnx:has(>.lnx-h>.lnx-tl)>.lnx-lg,:root [data-style="clean"].lnx:has(>.lnx-h>.lnx-tl)>.lnx-lg{grid-template-columns:1fr 1fr}}
:root[data-style="clean"] .lnx:has(>.lnx-h>.lnx-tl)>.lnx-lg .lnx-k[aria-pressed="true"],:root [data-style="clean"] .lnx:has(>.lnx-h>.lnx-tl)>.lnx-lg .lnx-k[aria-pressed="true"],:root [data-style="clean"].lnx:has(>.lnx-h>.lnx-tl)>.lnx-lg .lnx-k[aria-pressed="true"]{background:color-mix(in srgb,var(--dm-fg) 11%,var(--dm-surface))}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .lnx:has(>.lnx-h>.lnx-tl)>.lnx-lg .lnx-k[aria-pressed="false"]:hover,:root [data-style="clean"] .lnx:has(>.lnx-h>.lnx-tl)>.lnx-lg .lnx-k[aria-pressed="false"]:hover,:root [data-style="clean"].lnx:has(>.lnx-h>.lnx-tl)>.lnx-lg .lnx-k[aria-pressed="false"]:hover{background:var(--dm-hover)}}
:root[data-style="clean"] .lnx-tt,:root [data-style="clean"] .lnx-tt,:root [data-style="clean"].lnx-tt{padding:6px;border-radius:calc(14px * var(--dm-rk-l,var(--dm-rk)));transform:scale(.96);transition:opacity var(--dm-t-fast) var(--dm-ease),transform var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .lnx.on .lnx-tt,:root [data-style="clean"] .lnx.on .lnx-tt,:root [data-style="clean"].lnx.on .lnx-tt{transform:none}
:root[data-style="clean"] .lnx-tt-h,:root [data-style="clean"] .lnx-tt-h,:root [data-style="clean"].lnx-tt-h{padding:2px 8px 4px;border-bottom:0}
:root[data-style="clean"] .lnx-tt-r,:root [data-style="clean"] .lnx-tt-r,:root [data-style="clean"].lnx-tt-r,:root[data-style="clean"] .lnx-tt-r+.lnx-tt-r,:root [data-style="clean"] .lnx-tt-r+.lnx-tt-r,:root [data-style="clean"].lnx-tt-r+.lnx-tt-r{padding:5px 8px;border-radius:var(--dm-r-in)}
:root[data-style="clean"] .lnx-ax .lnx-tk,:root [data-style="clean"] .lnx-ax .lnx-tk,:root [data-style="clean"].lnx-ax .lnx-tk{border-radius:var(--dm-r-pill)}
/* Clean dark's accent is white (owner, 21 Nov; Clean dark's tokens): the line, its projection, its rings and "Now" are white,
   so the area under them is a little fainter; the comparison keeps the palette's violet */
:root[data-style="clean"][data-theme="dark"] .lnx,:root[data-theme="dark"] [data-style="clean"] .lnx,:root[data-theme="dark"] [data-style="clean"].lnx{--dm-lnx-fill:.16;--dm-lnx-pfill:.08}
@media (prefers-color-scheme:dark){:root[data-style="clean"]:not([data-theme="light"]) .lnx,:root:not([data-theme="light"]) [data-style="clean"] .lnx,:root:not([data-theme="light"]) [data-style="clean"].lnx{--dm-lnx-fill:.16;--dm-lnx-pfill:.08}}
@media (prefers-reduced-motion:reduce){:root[data-style="clean"] .lnx-tt,:root [data-style="clean"] .lnx-tt,:root [data-style="clean"].lnx-tt{transform:none}}
:root:not([data-style="soft"],[data-style="clean"]) .lnx-svg :is(.cmp,.prj):not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){stroke-dasharray:2 3}
:root:not([data-style="soft"],[data-style="clean"]) .lnx-now:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){background:linear-gradient(var(--dm-lnx-line),var(--dm-lnx-line)) center/4px 4px no-repeat,var(--dm-surface)}
:root:not([data-style="soft"],[data-style="clean"]) :is(.lnx-tt-r,.lnx-k).c i:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){background:repeating-linear-gradient(90deg,var(--dm-lnx-cmp) 0 2px,transparent 2px 4px)}
:root:not([data-style="soft"],[data-style="clean"]) :is(.lnx-tt-r,.lnx-k).p i:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){background:repeating-linear-gradient(90deg,var(--dm-lnx-line) 0 2px,transparent 2px 4px)}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, REDUCE, reveal, seg, tween } from '../core/core.js';
DM.def('line-chart', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{chev}', I('chev-d','xs'));
  const root = $('.lnx', r), ch = $('.lnx-ch', r), svg = $('.lnx-svg', r), yl = $('.lnx-y', r), ax = $('.lnx-ax', r), tt = $('.lnx-tt', r);
  const mark = $('.lnx-now', r), guide = $('.lnx-x', r), [pc, pm] = $$('.lnx-pt', r), pk = $('.lnx-pk', r), pp = $('.lnx-pp', r), live = $('p.lnx-sr', r), tab = $('.lnx-sr table', r);
  // the projects the picker offers: name, mark, the mark's colour, and how big each is next to the website
  const PJ = [['Website', 'W', 'b', 1], ['Mobile app', 'M', 'l', .58], ['Docs', 'D', 'm', .27]];
  // a small seeded wobble, so each project's numbers differ but are the same on every visit
  const wob = (s, i) => { const x = Math.sin(s * 91.7 + i * 12.9898) * 43758.5453; return x - Math.floor(x) - .5; };
  const HRS = Array.from({ length:24 }, (_, h) => (h % 12 || 12) + (h < 12 ? 'am' : 'pm'));
  const DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
  // editors at work: an hour of today (it is 2pm on Thursday 19 November), a day of this week, a day of this month. November
  // starts on a Sunday and October on a Thursday, so their weekends fall on different days
  const RG = {
    d:{ pts:HRS, ax:HRS, now:14, a:'Today', b:'Yesterday', each:'Hour', what:'today against yesterday', grid:[1, 2, 3, 4, 6, 12],
